window.docContents[94].resolve({"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Proof-of-Corollary-2___3___10/#Chapter2___Discussion_proof_Corollary2___3___10":{"contents":"Proof. Let \\lambda be an eigenvalue of \\phi (a root of the characteristic polynomial of \\phi). It exists since k is an algebraically closed field. Then the operator \\phi - \\lambda \\operatorname{Id} is an intertwining operator V \\to V, which is not an isomorphism (since its determinant is zero). Thus by Proposition 2.3.9 this operator is zero, hence the result. \\square\n\n\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.3. Representations\u0009Proof of Corollary 2.3.10","header":"Proof of Corollary 2.3.10","id":"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Proof-of-Corollary-2___3___10/#Chapter2___Discussion_proof_Corollary2___3___10"},"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Lie-algebra/#Chapter2___Definition2___9___1___formalization":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.9. Lie algebras\u0009Lie algebra\u0009Lie algebra","header":"Formalization","id":"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Lie-algebra/#Chapter2___Definition2___9___1___formalization"},"/3___-General-results-of-representation-theory/3___1___-Subrepresentations-in-semisimple-representations/Generalization-of-Proposition-3___1___4-to-non-algebraically-closed-fields/#Chapter3___Remark3___1___5___formalization":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\u00093. General results of representation theory\u00093.1. Subrepresentations in semisimple representations\u0009Generalization of Proposition 3.1.4 to non-algebraically-closed fields\u0009Generalization of Proposition 3.1.4 to non-algebraically-closed fields","header":"Formalization","id":"/3___-General-results-of-representation-theory/3___1___-Subrepresentations-in-semisimple-representations/Generalization-of-Proposition-3___1___4-to-non-algebraically-closed-fields/#Chapter3___Remark3___1___5___formalization"},"/3___-General-results-of-representation-theory/3___4___-Filtrations/Filtration-of-a-representation/#Chapter3___Definition3___4___1":{"contents":"Definition 3.4.1. A (finite) filtration of V is a sequence of subrepresentations 0 = V_0 \\subset V_1 \\subset \\cdots \\subset V_n = V.\n\n\n\n","context":"Introduction to Representation Theory\u00093. General results of representation theory\u00093.4. Filtrations\u0009Filtration of a representation","header":"Filtration of a representation","id":"/3___-General-results-of-representation-theory/3___4___-Filtrations/Filtration-of-a-representation/#Chapter3___Definition3___4___1"},"/7___-Introduction-to-categories/7___2___-Functors/Functor/#Chapter7___Definition7___2___1___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.2. Functors\u0009Functor\u0009Functor","header":"Formalization","id":"/7___-Introduction-to-categories/7___2___-Functors/Functor/#Chapter7___Definition7___2___1___formalization"}});